inline-block;margin-top:5px;padding:3px 6px;border:1px solid #000;border-radius:999px;font-size:8px;font-weight:900}.tag.pink{border-color:#ff008c;color:#ff008c}.paths{display:grid;gap:8px}.path{border:1px solid #000;border-radius:10px;overflow:hidden}.path summary{list-style:none;cursor:pointer;display:grid;grid-template-columns:34px 1.2fr 1fr;gap:10px;padding:11px 12px;align-items:center}.path summary::-webkit-details-marker{display:none}.path summary b{color:#ff008c}.path summary strong{font-size:14px}.path summary span{font-size:11px;color:rgba(0,0,0,.64)}.path-body{border-top:1px solid #000;padding:11px 12px;display:grid;grid-template-columns:repeat(5,1fr);gap:9px}.cell{border-left:3px solid #ff008c;padding-left:8px}.cell b{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.08em;margin-bottom:3px}.cell p{margin:0;font-size:11px}.call{margin-top:10px;padding:10px 12px;border:2px solid #ff008c;border-radius:10px}.timeline{display:grid;gap:7px}.event{display:grid;grid-template-columns:120px 1fr 1fr;gap:10px;padding:10px;border:1px solid #000;border-radius:10px}.event b{color:#ff008c}.event p{margin:2px 0;font-size:11px;color:rgba(0,0,0,.66)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.metric{border:1px solid #000;border-radius:9px;padding:10px}.metric strong{display:block;font-size:18px}.metric small{display:block;color:rgba(0,0,0,.58)}.flow{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.node{border:1px solid #000;border-radius:8px;padding:6px 8px}.arr{color:#ff008c;font-weight:900}@media(max-width:900px){body{overflow:auto}.shell{height:auto;display:block}.stage{overflow:visible}.panel,.panel.active,.section{height:auto;overflow:visible}.path-body{grid-template-columns:1fr 1fr}.event{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.compare-wrap{max-height:none}}@media(max-width:600px){.shell{padding:9px}.top{align-items:flex-start;flex-direction:column}.nav{position:sticky;top:0;background:#fff;pad